import{_ as o,o as i,c as t,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0037 — Registro delle funzioni, modulo @memobrain/cloud-features e client Go generato","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0037-registro-funzioni-e-cloud-features.md","filePath":"adr/0037-registro-funzioni-e-cloud-features.md"}'),a={name:"adr/0037-registro-funzioni-e-cloud-features.md"};function l(r,e,c,d,s,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0037-—-registro-delle-funzioni-modulo-memobrain-cloud-features-e-client-go-generato" tabindex="-1">ADR-0037 — Registro delle funzioni, modulo <code>@memobrain/cloud-features</code> e client Go generato <a class="header-anchor" href="#adr-0037-—-registro-delle-funzioni-modulo-memobrain-cloud-features-e-client-go-generato" aria-label="Permalink to &quot;ADR-0037 — Registro delle funzioni, modulo `@memobrain/cloud-features` e client Go generato&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.2 (2026-11-02): §2.5, §2.6.1, §2.6.6, §2.8.2, §3.1, §3.5.2, §4.1, §4.2, §4.4, §4.5 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.6.1 (creazione, rinomina, eliminazione logica e ripristino dei vault), §2.8 (spazio e dispositivi), §3.5 (API), §4.2 (frontend); D-02, D-05; ADR-0029, ADR-0030, ADR-0036</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no nei requisiti (li completa); sì nella struttura del frontend (§4.2) e nell&#39;elenco dei contratti generati (§3.5) → da recepire nello spec</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La parità tra desktop e workbench web è &quot;per costruzione&quot;: stessa UI (<code>@memobrain/workbench</code>) e stesso core Go (Wails sul desktop, WebAssembly nel browser, ADR-0029/0030). La <strong>gestione dei vault</strong> però vive in tre posti:</p><ol><li>il workbench, nei pannelli Cloud, Sync e Condivisione, che chiama i binding Go;</li><li>la console web (<code>web/src/pages</code>: Vaults, Devices, Usage, Shares), che chiama la REST tramite <code>@memobrain/api-client</code> generato da <code>api/openapi.yaml</code>;</li><li>il client REST Go del core (<code>apps/desktop/internal/sync/transport</code>), <strong>scritto a mano</strong> a imitazione del contratto.</li></ol><p>L&#39;analisi del 2026-11-01 ha misurato le conseguenze:</p><ul><li><strong>Comportamenti divergenti:</strong><ul><li>livello della quota (soglia locale nella console, livello del server nel workbench);</li><li>protezione del dispositivo corrente;</li><li>feature flag <code>sharing</code>, ignorato dalla console;</li><li>nomi e default dei flag definiti in tre punti.</li></ul></li><li><strong>Requisiti mancanti ovunque:</strong><ul><li>creazione di un vault cloud dalla console;</li><li><strong>rinomina, eliminazione logica e ripristino</strong> di un vault (§2.6.1), che il server espone già (<code>updateVault</code>, <code>deleteVault</code>, <code>restoreVault</code>) ma che nessun client usa;</li><li><code>PATCH /shares/{id}</code>, mai chiamato.</li></ul></li><li><strong>Un controllo di parità fragile:</strong><ul><li><code>scripts/parity.mjs</code> ricava i comandi da <code>registry.ts</code> con una regex e ne perde una quarantina (daily, bookmarks, workspaces, preview, drawing);</li><li>copre comandi e binding, non le <em>funzioni</em>;</li><li>non sa nulla della console.</li></ul></li><li><strong>Un contratto a rischio deriva:</strong> un cambiamento dell&#39;API rompe insieme desktop e workbench mentre la console continua a funzionare, perché solo il client TS è generato.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="_1-registro-delle-funzioni-shared-parity-features-yaml" tabindex="-1">1. Registro delle funzioni (<code>shared/parity/features.yaml</code>) <a class="header-anchor" href="#_1-registro-delle-funzioni-shared-parity-features-yaml" aria-label="Permalink to &quot;1. Registro delle funzioni (`shared/parity/features.yaml`)&quot;">​</a></h3><p>Un file dichiarativo, unica fonte della parità, con <strong>una voce per funzione utente</strong>: per esempio <code>vault.create</code>, <code>vault.rename</code>, <code>vault.delete</code>, <code>vault.restore</code>, <code>crypto.unlock</code>, <code>crypto.change-passphrase</code>, <code>crypto.recovery-key</code>, <code>share.create</code>, <code>share.update</code>, <code>share.grants</code>, <code>invitations</code>, <code>mounts</code>, <code>devices</code>, <code>usage</code>, <code>revisions</code>, <code>conflicts</code>, <code>trash</code>, <code>export.zip</code>, <code>import</code>, <code>settings</code>, <code>config.flags</code>.</p><p>Per ogni voce:</p><ul><li><strong>desktop / workbench:</strong> comandi (<code>commands[]</code>) e binding (<code>bindings[]</code>) che la realizzano, più l&#39;eventuale capability richiesta;</li><li><strong>console:</strong> rotte (<code>routes[]</code>) e operazioni OpenAPI (<code>operationIds[]</code>);</li><li><strong>stato per superficie:</strong> <code>yes | partial | exception | console-only | missing</code>, con la motivazione obbligatoria per tutto ciò che non è <code>yes</code>;</li><li><strong>test per target:</strong> spec o titoli di test desktop, web e cloud.</li></ul><p><code>scripts/parity.mjs</code> viene riscritto. Non usa più la regex sul sorgente:</p><ul><li>importa il registro dei comandi a runtime (via <code>tsx</code>, con <code>configurePlatform(&#39;web&#39;)</code>) e legge un nuovo campo dichiarativo <code>Command.requires?: (keyof Capabilities)[]</code>;</li><li>legge i binding generati e gli <code>operationId</code> di <code>api/openapi.yaml</code>.</li></ul><p><code>parity --check</code> (incluso in <code>task ci</code>, ADR-0036) <strong>fallisce</strong> in tre casi:</p><ul><li>un comando, un binding o un&#39;operazione utente non compare in nessuna voce;</li><li>una voce rimanda a un elemento che non esiste;</li><li>uno stato diverso da <code>yes</code> non ha motivazione.</li></ul><p><code>docs/web-workbench-parity.md</code> resta generato, con una nuova tabella per funzione.</p><h3 id="_2-modulo-memobrain-cloud-features-con-cloudport" tabindex="-1">2. Modulo <code>@memobrain/cloud-features</code> con <code>CloudPort</code> <a class="header-anchor" href="#_2-modulo-memobrain-cloud-features-con-cloudport" aria-label="Permalink to &quot;2. Modulo `@memobrain/cloud-features` con `CloudPort`&quot;">​</a></h3><p>Un nuovo pacchetto TypeScript (<code>packages/cloud-features</code>) contiene <strong>tutta la UI di gestione dei vault cloud</strong>, una volta sola:</p><ul><li><code>CloudVaultsTable</code>: elenco, creazione, rinomina, eliminazione, sezione dei vault eliminati con ripristino;</li><li><code>DevicesPanel</code>, con il dispositivo corrente protetto;</li><li><code>UsagePanel</code>: livello del server, dettaglio per vault;</li><li><code>SharesManager</code>, <code>InvitationsList</code>, <code>GrantEditor</code>, ricerca nella directory.</li></ul><p>I componenti dipendono solo da un&#39;interfaccia <code>CloudPort</code> (vault, dispositivi, utilizzo, condivisioni, grant, inviti, directory, configurazione effettiva). I tipi dei dati sono quelli generati da OpenAPI (<code>@memobrain/api-client</code>). Due adattatori:</p><ul><li><strong><code>RestCloudPort</code></strong> per la console (REST, <code>unwrap()</code>/<code>ApiError</code>);</li><li><strong><code>CoreCloudPort</code></strong> per desktop e workbench (binding Go).</li></ul><p>Una sola suite di test dei componenti gira su entrambi gli adattatori.</p><p>La migrazione procede <strong>pannello per pannello</strong>. La prima funzione nuova a nascere nel pacchetto è il <strong>ciclo di vita dei vault</strong> (creazione, rinomina, eliminazione logica, ripristino) su console e desktop:</p><ul><li>nuovi metodi <code>SyncAPI.RenameCloudVault</code>, <code>DeleteCloudVault</code>, <code>RestoreCloudVault</code>, più l&#39;elenco dei vault eliminati;</li><li><strong>effetto locale di un&#39;eliminazione:</strong> il dispositivo collegato si scollega e <strong>conserva i file</strong>, mai una cancellazione locale (D-04);</li><li>un <strong>vault privato</strong> si crea nel browser solo nel workbench, che contiene il codice crittografico Go (envelope, recovery key). La console apre il workbench su una rotta di creazione e non duplica la crittografia in TypeScript.</li></ul><p>Se il server non elenca i vault eliminati, si aggiunge un parametro all&#39;API: <code>GET /vaults?include_deleted=true</code>, compatibile all&#39;indietro.</p><p>Regola per il futuro: ogni funzione di gestione dei vault cloud nasce in <code>@memobrain/cloud-features</code>, mai direttamente in <code>web/src/pages</code> o in <code>packages/workbench/src/settings</code>.</p><p><strong>Attuazione della fase B (2026-11-01).</strong> Scelte fatte realizzando il ciclo di vita dei vault (dettagli in <code>packages/cloud-features/README.md</code>):</p><ul><li><code>CoreCloudPort</code> sta in <code>packages/workbench/src/cloud</code>, accanto alla facciata dei binding: il pacchetto definisce solo l&#39;interfaccia e la dipendenza va in un verso (workbench → cloud-features);</li><li>i componenti usano <code>@memobrain/ui</code>; il workbench carica solo le regole dei componenti (<code>@memobrain/ui/components.css</code>) con i token mappati sui propri (<code>workbench.css</code>), senza stile inline;</li><li>i testi it/en stanno nel pacchetto, l&#39;host passa la lingua;</li><li>binding: <code>SyncAPI.ListDeletedCloudVaults</code>, <code>RenameCloudVault</code>, <code>DeleteCloudVault</code>, <code>RestoreCloudVault</code>; il DTO <code>CloudVault</code> aggiunge <code>ownerId</code>, <code>lastSeq</code> e <code>deletedAt</code> (superato da ADR-0045 §6, M12-W5.3: i binding cloud restituiscono ora i tipi dell&#39;OpenAPI, con i campi in snake_case come la REST, e <code>CoreCloudPort</code> non rimappa più);</li><li>rotta di creazione dei vault privati: <code>/vaults/new/open?kind=private&amp;name=…</code>.</li></ul><h3 id="_3-un-solo-contratto-per-la-rest" tabindex="-1">3. Un solo contratto per la REST <a class="header-anchor" href="#_3-un-solo-contratto-per-la-rest" aria-label="Permalink to &quot;3. Un solo contratto per la REST&quot;">​</a></h3><ul><li><strong>Client Go generato:</strong> oapi-codegen genera da <code>api/openapi.yaml</code> i tipi (e il client) in <code>shared/go/apiclient</code>, nell&#39;ambito di <code>task gen-openapi</code>.</li><li><strong><code>sync/transport</code> diventa un involucro sottile:</strong> retry, chiave di idempotenza, decodifica di <code>problem+json</code>, request id. Le strutture copiate a mano spariscono e i metodi morti si rimuovono o si collegano a una funzione del registro.</li><li><strong>Contract test nella suite d&#39;integrazione del cloud:</strong> ogni richiesta e risposta di <code>transport</code> viene validata contro <code>openapi.yaml</code> (kin-openapi <code>openapi3filter</code>). Un test allinea l&#39;enum <code>ErrorCode</code> alle costanti di <code>shared/go/syncproto</code>.</li><li><strong>Fuori dal generatore:</strong> tus e lo stream SSE (<code>/events</code>) restano fuori dall&#39;interfaccia generata, ma vengono documentati nell&#39;OpenAPI come rotte esterne.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Lasciare tre implementazioni e coprire con più e2e:</strong> i test troverebbero le divergenze dopo, senza impedirle. Ogni funzione nuova andrebbe comunque scritta tre volte. Scartata.</li><li><strong>Console che usa il core WASM per tutto:</strong> una sola implementazione, ma 8 MB di core e un worker per mostrare un elenco di dispositivi. Contraddice anche la scelta di tenere la console leggera, con una CSP stretta. Scartata, tranne per la creazione dei vault privati, dove la crittografia lo impone.</li><li><strong>Registro in TypeScript invece che in YAML:</strong> più comodo per il frontend, ma il registro deve essere letto anche da script e test Go. Scartato.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Positive:</strong><ul><li>una funzione di gestione dei vault esiste su desktop, workbench e console per costruzione;</li><li>il controllo di parità copre le funzioni, non solo i nomi;</li><li>una deriva dell&#39;API rompe la compilazione o un contract test, non un utente;</li><li>si chiudono i requisiti mancanti di §2.6.1.</li></ul></li><li><strong>Costi:</strong><ul><li>un pacchetto in più;</li><li>i componenti della console e del workbench vanno migrati;</li><li>i binding Go dovranno restituire tipi compatibili con quelli OpenAPI (mappatura nell&#39;adattatore finché non è così);</li><li>il registro va tenuto aggiornato: è il prezzo del controllo, e la CI locale lo rende esplicito.</li></ul></li><li><strong>Spec:</strong> §4.2 (struttura del frontend) e §3.5 (contratti generati) vanno aggiornati. Se serve <code>include_deleted</code>, va aggiunto all&#39;API.</li></ul>',35)])])}const m=o(a,[["render",l]]);export{g as __pageData,m as default};
